        LightViewProj1 = new Float4x4EffectParameter(SlotOf(reflection, "LightViewProj1"));
        LightViewProj2 = new Float4x4EffectParameter(SlotOf(reflection, "LightViewProj2"));
        DepthBias = new FloatEffectParameter(SlotOf(reflection, "DepthBias"));
        NumCascades = new FloatEffectParameter(SlotOf(reflection, "NumCascades"));
        LightDirection = new Float3EffectParameter(SlotOf(reflection, "LightDirection"));
        View = new Float4x4EffectParameter(SlotOf(reflection, "View"));
        Projection = new Float4x4EffectParameter(SlotOf(reflection, "Projection"));
        ViewProj = new Float4x4EffectParameter(SlotOf(reflection, "ViewProj"));
        SnapColor = new Float3EffectParameter(SlotOf(reflection, "SnapColor"));
        IsFullbright = new BoolEffectParameter(SlotOf(reflection, "IsFullbright"));
        UseBaseColor = new BoolEffectParameter(SlotOf(reflection, "UseBaseColor"));
        BaseColor = new Float3EffectParameter(SlotOf(reflection, "BaseColor"));
        FogColor = new Float3EffectParameter(SlotOf(reflection, "FogColor"));
        FogDistance = new FloatEffectParameter(SlotOf(reflection, "FogDistance"));
        FogLogDensity = new FloatEffectParameter(SlotOf(reflection, "FogLogDensity"));
        EnvironmentLight = new Float2EffectParameter(SlotOf(reflection, "EnvironmentLight"));
        CameraPosition = new Float3EffectParameter(SlotOf(reflection, "CameraPosition"));
        Alpha = new FloatEffectParameter(SlotOf(reflection, "Alpha"));
        Expand = new BoolEffectParameter(SlotOf(reflection, "Expand"));
        RandomFloat = new FloatEffectParameter(SlotOf(reflection, "RandomFloat"));
        Darken = new FloatEffectParameter(SlotOf(reflection, "Darken"));
        ShadowMap0 = new TextureEffectParameter(TextureSlotOf(reflection, "ShadowMap0"));
        ShadowMap1 = new TextureEffectParameter(TextureSlotOf(reflection, "ShadowMap1"));
        ShadowMap2 = new TextureEffectParameter(TextureSlotOf(reflection, "ShadowMap2"));
    }

    public Float4x4EffectParameter LightViewProj0 { get; }
    public Float4x4EffectParameter LightViewProj1 { get; }
    public Float4x4EffectParameter LightViewProj2 { get; }
    public FloatEffectParameter DepthBias { get; }
    public FloatEffectParameter NumCascades { get; }
    public Float3EffectParameter LightDirection { get; }
    public Float4x4EffectParameter View { get; }
    public Float4x4EffectParameter Projection { get; }
    public Float4x4EffectParameter ViewProj { get; }
    public Float3EffectParameter SnapColor { get; }
    public BoolEffectParameter IsFullbright { get; }
    public BoolEffectParameter UseBaseColor { get; }
    public Float3EffectParameter BaseColor { get; }
    public Float3EffectParameter FogColor { get; }
    public FloatEffectParameter FogDistance { get; }
    public FloatEffectParameter FogLogDensity { get; }
    public Float2EffectParameter EnvironmentLight { get; }
    public Float3EffectParameter CameraPosition { get; }
    public FloatEffectParameter Alpha { get; }
    public BoolEffectParameter Expand { get; }
    public FloatEffectParameter RandomFloat { get; }
    public FloatEffectParameter Darken { get; }
    public TextureEffectParameter ShadowMap0 { get; }
    public TextureEffectParameter ShadowMap1 { get; }
    public TextureEffectParameter ShadowMap2 { get; }

    // -1 ("not found") mirrors the old FNA model's "parameter != null" check for a
    // uniform the HLSL compiler optimized out - every *EffectParameter.SetValue below
